function fresh(){let ring=shuffle(teams.map(t=>t.id)),rounds=[];for(let r=0;r<31;r++){let ms=[];for(let i=0;i<16;i++)ms.push(match(ring[i],ring[31-i],`L${r}-${i}`));rounds.push(ms);ring.splice(1,0,ring.pop());}return{version:1,rounds,tie:shuffle(teams.map(t=>t.id)),playin:null,bracket:null};}
