function validate(sets){if(!Array.isArray(sets)||sets.length<3||sets.length>5)return false;let w=0,l=0;for(let i=0;i<sets.length;i++){if(w===3||l===3)return false;let [a,b]=sets[i],t=i===4?15:25;if(!Number.isInteger(a)||!Number.isInteger(b)||a<0||b<0||Math.max(a,b)<t||Math.abs(a-b)<2)return false;if(Math.max(a,b)>t&&Math.abs(a-b)!==2)return false;a>b?w++:l++;}return w===3||l===3;}
function standings(s){let rows=teams.map(t=>({...t,w:0,l:0,sf:0,sa:0,pf:0,pa:0})),map=Object.fromEntries(rows.map(t=>[t.id,t]));for(const m of s.rounds.flat()){if(!m.sets)continue;let[a,b]=score(m),x=map[m.a],y=map[m.b];x.sf+=a;x.sa+=b;y.sf+=b;y.sa+=a;a>b?(x.w++,y.l++):(y.w++,x.l++);for(const[p,q]of m.sets){x.pf+=p;x.pa+=q;y.pf+=q;y.pa+=p;}}const primary=(a,b)=>b.w-a.w||a.l-b.l||(b.sf-b.sa)-(a.sf-a.sa)||(b.pf-b.pa)-(a.pf-a.pa);rows.sort(primary);for(let i=0;i<rows.length;){let j=i+1;while(j<rows.length&&!primary(rows[i],rows[j]))j++;const group=rows.slice(i,j),ids=new Set(group.map(x=>x.id)),hw=Object.fromEntries(group.map(x=>[x.id,0]));for(const m of s.rounds.flat())if(m.sets&&ids.has(m.a)&&ids.has(m.b))hw[winner(m)]++;group.sort((a,b)=>hw[b.id]-hw[a.id]||s.tie.indexOf(a.id)-s.tie.indexOf(b.id));rows.splice(i,j-i,...group);i=j;}return rows;}
